// Generar lotes de 500 para evitar desbordamiento de memoria
const batchSize = 500;
const maxClients = 10000; // Asumimos max 10k por ahora
const batches = [];

for (let i = 0; i < maxClients; i += batchSize) {
  batches.push({
    json: {
      offset: i,
      limit: batchSize,
      batchNumber: (i / batchSize) + 1
    }
  });
}

return batches;

// Transformar clientes del lote actual
const clientes = [];

for (const item of $input.all()) {
  const c = item.json;

  // Solo procesar si tiene teléfono válido
  if (!c.phone || c.phone.trim() === '') continue;

  // Normalizar teléfono
  let telefonoNormalizado = c.phone.replace(/[^0-9]/g, '');

  // Asegurar prefijo 57 si es número colombiano (10 dígitos)
  if (telefonoNormalizado.length === 10 && telefonoNormalizado.startsWith('3')) {
      telefonoNormalizado = '57' + telefonoNormalizado;
  }

  clientes.push({
    supabase_id: c.id,
    telefono: telefonoNormalizado,
    nombre: c.name || null,
    email: c.email || null,
    direccion: c.address || null,
    ciudad: c.city || 'Bogotá',
    total_pedidos: c.total_orders || 0,
    total_gastado: c.total_spent || 0,
    is_active: c.is_active !== false,
    synced_at: new Date().toISOString()
  });
}

// Si el lote está vacío (ej. offset > total real), retornamos vacío para que el siguiente nodo no falle
if (clientes.length === 0) {
    return [];
}

return clientes.map(c => ({ json: c }));
